REPLACE INTO `global_property` VALUES ('emrapi.sqlSearch.hei','select distinct\r\n          concat(pn.given_name,\' \', ifnull(pn.family_name,\'\')) as name,\r\n          pi.identifier as identifier,\r\n          concat(\"\",p.uuid) as uuid,\r\n          concat(\"\",v.uuid) as activeVisitUuid,\r\n          IF(va.value_reference = \"Admitted\", \"true\", \"false\") as hasBeenAdmitted\r\n        from visit v\r\n        join person_name pn on v.patient_id = pn.person_id and pn.voided = 0\r\n        join patient_identifier pi on v.patient_id = pi.patient_id\r\n        join patient_identifier_type pit on pi.identifier_type = pit.patient_identifier_type_id\r\n        join global_property gp on gp.property=\"bahmni.primaryIdentifierType\" and gp.property_value=pit.uuid\r\n        join person p on p.person_id = v.patient_id\r\n		join encounter en on en.visit_id = v.visit_id and en.voided=0\r\n        join location l on l.uuid = ${visit_location_uuid} and v.location_id = l.location_id\r\n        left outer join visit_attribute va on va.visit_id = v.visit_id and va.attribute_type_id = (\r\n          select visit_attribute_type_id from visit_attribute_type where name=\"Admission Status\"\r\n        ) and va.voided = 0\r\nwhere\r\nv.date_stopped is null and\r\nv.visit_type_id=18\r\norder by en.encounter_datetime asc',NULL,'761dcbf4-6a78-4f5d-915a-25816d00b1de',NULL,NULL,NULL,NULL,NULL,NULL);
REPLACE INTO `global_property` VALUES ('emrapi.sqlSearch.highRiskPatients','SELECT DISTINCT\r\n  concat(pn.given_name, \" \", ifnull(pn.family_name,\'\'))           AS name,\r\n  pi.identifier                                        AS identifier,\r\n  concat(\"\", p.uuid)                                   AS uuid,\r\n  concat(\"\", v.uuid)                                   AS activeVisitUuid,\r\n  IF(va.value_reference = \"Admitted\", \"true\", \"false\") AS hasBeenAdmitted\r\nFROM person p\r\n  INNER JOIN person_name pn ON pn.person_id = p.person_id\r\n  INNER JOIN patient_identifier pi ON pn.person_id = pi.patient_id\r\n  INNER JOIN patient_identifier_type pit on pi.identifier_type = pit.patient_identifier_type_id\r\n  INNER JOIN global_property gp on gp.property=\"bahmni.primaryIdentifierType\" and gp.property_value=pit.uuid\r\n  INNER JOIN visit v ON v.patient_id = p.person_id AND v.date_stopped IS NULL AND v.voided = 0\r\n  INNER JOIN (SELECT\r\n                max(test_obs.obs_group_id) AS max_id,\r\n                test_obs.concept_id,\r\n                test_obs.person_id\r\n              FROM obs test_obs\r\n                INNER JOIN concept c ON c.concept_id = test_obs.concept_id AND test_obs.voided = 0\r\n                INNER JOIN concept_name cn\r\n                  ON c.concept_id = cn.concept_id AND cn.concept_name_type = \"FULLY_SPECIFIED\" AND\r\n                     cn.name IN (${testName})\r\n              GROUP BY test_obs.person_id, test_obs.concept_id) AS tests ON tests.person_id = v.patient_id\r\n  INNER JOIN obs abnormal_obs\r\n    ON abnormal_obs.obs_group_id = tests.max_id AND abnormal_obs.value_coded = 1 AND abnormal_obs.voided = 0\r\n  INNER JOIN concept abnormal_concept ON abnormal_concept.concept_id = abnormal_obs.concept_id\r\n  INNER JOIN concept_name abnormal_concept_name\r\n    ON abnormal_concept.concept_id = abnormal_concept_name.concept_id AND\r\n       abnormal_concept_name.concept_name_type = \"FULLY_SPECIFIED\" AND\r\n       abnormal_concept_name.name IN (\"LAB_ABNORMAL\")\r\n  LEFT OUTER JOIN visit_attribute va ON va.visit_id = v.visit_id AND va.attribute_type_id =\r\n                                                                     (SELECT visit_attribute_type_id\r\n                                                                      FROM visit_attribute_type\r\n                                                                      WHERE name = \"Admission Status\")','SQL QUERY TO get LIST of patients with high risk','71ba1160-36e8-11e7-be35-080027e99513',NULL,NULL,NULL,NULL,NULL,NULL);
REPLACE INTO `global_property` VALUES ('emrapi.sqlSearch.highviralload','select distinct\r\n          concat(pn.given_name,\' \', ifnull(pn.family_name,\'\')) as name,\r\n          pi.identifier as identifier,\r\n          concat(\"\",p.uuid) as uuid,\r\n          concat(\"\",v.uuid) as activeVisitUuid,\r\n          IF(va.value_reference = \"Admitted\", \"true\", \"false\") as hasBeenAdmitted,\r\n          IF(datediff(now(), obs_blooddrawdue.value_datetime) >= 182.62, \"true\", \"false\") as BloodDrawDue\r\nfrom visit v\r\n        join person_name pn on v.patient_id = pn.person_id and pn.voided = 0\r\n        join patient_identifier pi on v.patient_id = pi.patient_id\r\n        join patient_identifier_type pit on pi.identifier_type = pit.patient_identifier_type_id\r\n        join global_property gp on gp.property=\"bahmni.primaryIdentifierType\" and gp.property_value=pit.uuid\r\n        join person p on p.person_id = v.patient_id\r\n		join encounter en on en.visit_id = v.visit_id and en.voided=0		\r\n		left outer JOIN (SELECT\r\n				max(test_obs.obs_group_id) AS max_id,\r\n				test_obs.concept_id,\r\n				test_obs.person_id\r\n			FROM obs test_obs\r\n			INNER JOIN concept c ON c.concept_id = test_obs.concept_id AND test_obs.voided = 0\r\n			INNER JOIN concept_name cn\r\n			  ON c.concept_id = cn.concept_id AND cn.concept_name_type = \"FULLY_SPECIFIED\" AND\r\n				 cn.name IN (\'HIVTC, Viral Load Blood drawn date\')\r\n			GROUP BY test_obs.person_id, test_obs.concept_id) AS tests ON tests.person_id = v.patient_id\r\n		left outer join obs obs_blooddrawdue on obs_blooddrawdue.obs_group_id=tests.max_id and obs_blooddrawdue.concept_id=4267\r\n			and obs_blooddrawdue.voided=0\r\n        join location l on l.uuid = ${visit_location_uuid} and v.location_id = l.location_id\r\n        left outer join visit_attribute va on va.visit_id = v.visit_id and va.attribute_type_id = (\r\n          select visit_attribute_type_id from visit_attribute_type where name=\"Admission Status\"\r\n        ) and va.voided = 0\r\nwhere\r\nv.date_stopped is null and\r\nv.visit_type_id=12\r\norder by en.encounter_datetime asc',NULL,'647c7cbf-83de-44e6-a9a6-f33e4e8d3feb',NULL,NULL,NULL,NULL,NULL,NULL);
REPLACE INTO `global_property` VALUES ('emrapi.sqlSearch.htsonly','select distinct\r\n          p.person_id,\r\n          concat(pn.given_name,\' \', ifnull(pn.family_name,\'\')) as name,\r\n          pi.identifier as identifier,\r\n		  concat(\"\",p.uuid) as uuid,\r\n          concat(\"\",v.uuid) as activeVisitUuid,\r\n          IF(va.value_reference = \"Admitted\", \"true\", \"false\") as hasBeenAdmitted,\r\n                  if(obs_positive.value_coded=1738, \"true\", \"false\") as CodedP\r\n        from visit v\r\n        join person_name pn on v.patient_id = pn.person_id and pn.voided = 0\r\n        join patient_identifier pi on v.patient_id = pi.patient_id\r\n        join patient_identifier_type pit on pi.identifier_type = pit.patient_identifier_type_id\r\n        join global_property gp on gp.property=\"bahmni.primaryIdentifierType\" and gp.property_value=pit.uuid\r\n        join person p on p.person_id = v.patient_id\r\n		join encounter en on en.visit_id = v.visit_id and en.voided=0\r\n		left outer JOIN (SELECT\r\n				max(test_obs.obs_group_id) AS max_id,\r\n				test_obs.concept_id,\r\n				test_obs.person_id\r\n			FROM obs test_obs\r\n			INNER JOIN concept c ON c.concept_id = test_obs.concept_id AND test_obs.voided = 0\r\n			INNER JOIN concept_name cn\r\n			  ON c.concept_id = cn.concept_id AND cn.concept_name_type = \"FULLY_SPECIFIED\" AND\r\n				 cn.name IN (\'HTC, Final HIV status\')\r\n			GROUP BY test_obs.person_id, test_obs.concept_id) AS tests ON tests.person_id = v.patient_id\r\n		left outer join obs obs_positive on obs_positive.obs_group_id=tests.max_id and obs_positive.value_coded=1738\r\n			and obs_positive.voided=0\r\n        join location l on v.location_id = l.location_id\r\n        left outer join visit_attribute va on va.visit_id = v.visit_id and va.attribute_type_id = (\r\n          select visit_attribute_type_id from visit_attribute_type where name=\"Admission Status\"\r\n        ) and va.voided = 0\r\nwhere\r\nv.date_stopped is null and\r\nv.visit_type_id=15\r\norder by en.encounter_datetime asc',NULL,'dc1d0217-5d58-4773-82bc-2fb817797d3e',NULL,NULL,NULL,NULL,NULL,NULL);
REPLACE INTO `global_property` VALUES ('emrapi.sqlSearch.htspositivelinkedtocare','select distinct\r\n          concat(pn.given_name,\' \', ifnull(pn.family_name,\'\')) as name,\r\n          pi.identifier as identifier,\r\n          concat(\"\",p.uuid) as uuid,\r\n          concat(\"\",v.uuid) as activeVisitUuid,\r\n          IF(va.value_reference = \"Admitted\", \"true\", \"false\") as hasBeenAdmitted\r\n        from visit v\r\n        join person_name pn on v.patient_id = pn.person_id and pn.voided = 0\r\n        join patient_identifier pi on v.patient_id = pi.patient_id\r\n        join patient_identifier_type pit on pi.identifier_type = pit.patient_identifier_type_id\r\n        join global_property gp on gp.property=\"bahmni.primaryIdentifierType\" and gp.property_value=pit.uuid\r\n        join person p on p.person_id = v.patient_id\r\n		join encounter en on en.visit_id = v.visit_id and en.voided=0\r\n		join obs obs_linked on obs_linked.encounter_id=en.encounter_id and obs_linked.person_id=p.person_id\r\n		and obs_linked.concept_id=4239 and obs_linked.value_coded=2146\r\n		join obs obs_positive on obs_positive.encounter_id=en.encounter_id and obs_positive.person_id=p.person_id\r\n		and obs_positive.concept_id=2165 and obs_positive.value_coded=1738\r\n        join location l on v.location_id = l.location_id\r\n        left outer join visit_attribute va on va.visit_id = v.visit_id and va.attribute_type_id = (\r\n          select visit_attribute_type_id from visit_attribute_type where name=\"Admission Status\"\r\n        ) and va.voided = 0\r\nwhere\r\nv.date_stopped is null and\r\nv.visit_type_id=15\r\norder by en.encounter_datetime asc',NULL,'236b2f2f-5c77-480b-a18d-df0f5f3502b0',NULL,NULL,NULL,NULL,NULL,NULL);
REPLACE INTO `global_property` VALUES ('emrapi.sqlSearch.neworpreart','select distinct\r\n          concat(pn.given_name,\' \', ifnull(pn.family_name,\'\')) as name,\r\n          pi.identifier as identifier,\r\n          concat(\"\",p.uuid) as uuid,\r\n          concat(\"\",v.uuid) as activeVisitUuid,\r\n          IF(va.value_reference = \"Admitted\", \"true\", \"false\") as hasBeenAdmitted\r\n        from visit v\r\n        join person_name pn on v.patient_id = pn.person_id and pn.voided = 0\r\n        join patient_identifier pi on v.patient_id = pi.patient_id\r\n        join patient_identifier_type pit on pi.identifier_type = pit.patient_identifier_type_id\r\n        join global_property gp on gp.property=\"bahmni.primaryIdentifierType\" and gp.property_value=pit.uuid\r\n        join person p on p.person_id = v.patient_id\r\n		join encounter en on en.visit_id = v.visit_id and en.voided=0\r\n        join location l on l.uuid = ${visit_location_uuid} and v.location_id = l.location_id\r\n        left outer join visit_attribute va on va.visit_id = v.visit_id and va.attribute_type_id = (\r\n          select visit_attribute_type_id from visit_attribute_type where name=\"Admission Status\"\r\n        ) and va.voided = 0\r\nwhere\r\nv.date_stopped is null and\r\nv.visit_type_id=9\r\norder by en.encounter_datetime asc',NULL,'1086fc26-0f7e-44c4-801e-ca6d57f8d525',NULL,NULL,NULL,NULL,NULL,NULL);
REPLACE INTO `global_property` VALUES ('emrapi.sqlSearch.patientsHasPendingOrders','select distinct\r\n          concat(pn.given_name, \" \", ifnull(pn.family_name,\'\')) as name,\r\n          pi.identifier as identifier,\r\n          concat(\"\",p.uuid) as uuid,\r\n          concat(\"\",v.uuid) as activeVisitUuid,\r\n          IF(va.value_reference = \"Admitted\", \"true\", \"false\") as hasBeenAdmitted\r\n        from visit v\r\n        join person_name pn on v.patient_id = pn.person_id and pn.voided = 0\r\n        join patient_identifier pi on v.patient_id = pi.patient_id\r\n        join patient_identifier_type pit on pi.identifier_type = pit.patient_identifier_type_id\r\n        join global_property gp on gp.property=\"bahmni.primaryIdentifierType\" and gp.property_value=pit.uuid\r\n        join person p on p.person_id = v.patient_id\r\n        join orders on orders.patient_id = v.patient_id\r\n        join order_type on orders.order_type_id = order_type.order_type_id and order_type.name != \"Order\" and order_type.name != \"Drug Order\"\r\n        left outer join visit_attribute va on va.visit_id = v.visit_id and va.voided = 0 and va.attribute_type_id =\r\n          (select visit_attribute_type_id from visit_attribute_type where name=\"Admission Status\")\r\n        where v.date_stopped is null AND v.voided = 0 and order_id not in\r\n          (select obs.order_id\r\n            from obs\r\n          where person_id = pn.person_id and order_id = orders.order_id)','Sql query to get list of patients who has pending orders','71ba1bf0-36e8-11e7-be35-080027e99513',NULL,NULL,NULL,NULL,NULL,NULL);
REPLACE INTO `global_property` VALUES ('emrapi.sqlSearch.patientsToAdmit','select distinct concat(pn.given_name,\' \', ifnull(pn.family_name,\'\')) as name,\r\n        pi.identifier as identifier,\r\n        concat(\"\",p.uuid) as uuid,\r\n        concat(\"\",v.uuid) as activeVisitUuid\r\n        from visit v\r\n        join person_name pn on v.patient_id = pn.person_id and pn.voided = 0 AND v.voided = 0\r\n        join patient_identifier pi on v.patient_id = pi.patient_id\r\n        join patient_identifier_type pit on pi.identifier_type = pit.patient_identifier_type_id\r\n        join global_property gp on gp.property=\"bahmni.primaryIdentifierType\" and gp.property_value=pit.uuid\r\n        join person p on v.patient_id = p.person_id\r\n        join encounter e on v.visit_id = e.visit_id\r\n        join obs o on e.encounter_id = o.encounter_id and o.voided = 0\r\n        join concept c on o.value_coded = c.concept_id\r\n        join concept_name cn on c.concept_id = cn.concept_id\r\n        join location l on l.uuid=${visit_location_uuid} and v.location_id = l.location_id\r\n        where v.date_stopped is null and cn.name = \'Admit Patient\' and v.visit_id not in (select visit_id\r\n        from encounter ie join encounter_type iet\r\n        on iet.encounter_type_id = ie.encounter_type\r\n        where iet.name = \'ADMISSION\')','Sql query to get list of patients to be admitted','71b9d436-36e8-11e7-be35-080027e99513',NULL,NULL,NULL,NULL,NULL,NULL);
REPLACE INTO `global_property` VALUES ('emrapi.sqlSearch.patientsToDischarge','SELECT DISTINCT\r\n          concat(pn.given_name, \' \', ifnull(pn.family_name,\'\')) AS name,\r\n          pi.identifier AS identifier,\r\n          concat(\"\", p.uuid) AS uuid,\r\n          concat(\"\", v.uuid) AS activeVisitUuid,\r\n          IF(va.value_reference = \"Admitted\", \"true\", \"false\") as hasBeenAdmitted\r\n        FROM visit v\r\n        INNER JOIN person_name pn ON v.patient_id = pn.person_id and pn.voided is FALSE\r\n        INNER JOIN patient_identifier pi ON v.patient_id = pi.patient_id and pi.voided is FALSE\r\n        INNER JOIN patient_identifier_type pit on pi.identifier_type = pit.patient_identifier_type_id\r\n        INNER JOIN global_property gp on gp.property=\"bahmni.primaryIdentifierType\" and gp.property_value=pit.uuid\r\n        INNER JOIN person p ON v.patient_id = p.person_id\r\n        Inner Join (SELECT DISTINCT v.visit_id\r\n          FROM encounter en\r\n          INNER JOIN visit v ON v.visit_id = en.visit_id AND en.encounter_type =\r\n            (SELECT encounter_type_id\r\n              FROM encounter_type\r\n            WHERE name = \"ADMISSION\")) v1 on v1.visit_id = v.visit_id\r\n        INNER JOIN encounter e ON v.visit_id = e.visit_id\r\n        INNER JOIN obs o ON e.encounter_id = o.encounter_id\r\n        INNER JOIN concept_name cn ON o.value_coded = cn.concept_id AND cn.concept_name_type = \"FULLY_SPECIFIED\" AND cn.voided is FALSE\r\n        JOIN location l on l.uuid=${visit_location_uuid} and v.location_id = l.location_id\r\n        left outer join visit_attribute va on va.visit_id = v.visit_id and va.attribute_type_id =\r\n          (select visit_attribute_type_id from visit_attribute_type where name=\"Admission Status\")\r\n        LEFT OUTER JOIN encounter e1 ON e1.visit_id = v.visit_id AND e1.encounter_type = (\r\n          SELECT encounter_type_id\r\n            FROM encounter_type\r\n          WHERE name = \"DISCHARGE\") AND e1.voided is FALSE\r\n        WHERE v.date_stopped IS NULL AND v.voided = 0 AND o.voided = 0 AND cn.name = \"Discharge Patient\" AND e1.encounter_id IS NULL','Sql query to get list of patients to discharge','71b9f236-36e8-11e7-be35-080027e99513',NULL,NULL,NULL,NULL,NULL,NULL);
REPLACE INTO `global_property` VALUES ('emrapi.sqlSearch.pnc','select distinct\r\n          concat(pn.given_name,\' \', ifnull(pn.family_name,\'\')) as name,\r\n          pi.identifier as identifier,\r\n          concat(\"\",p.uuid) as uuid,\r\n          concat(\"\",v.uuid) as activeVisitUuid,\r\n          IF(va.value_reference = \"Admitted\", \"true\", \"false\") as hasBeenAdmitted\r\n        from visit v\r\n        join person_name pn on v.patient_id = pn.person_id and pn.voided = 0\r\n        join patient_identifier pi on v.patient_id = pi.patient_id\r\n        join patient_identifier_type pit on pi.identifier_type = pit.patient_identifier_type_id\r\n        join global_property gp on gp.property=\"bahmni.primaryIdentifierType\" and gp.property_value=pit.uuid\r\n        join person p on p.person_id = v.patient_id\r\n		join encounter en on en.visit_id = v.visit_id and en.voided=0\r\n        join location l on l.uuid = ${visit_location_uuid} and v.location_id = l.location_id\r\n        left outer join visit_attribute va on va.visit_id = v.visit_id and va.attribute_type_id = (\r\n          select visit_attribute_type_id from visit_attribute_type where name=\"Admission Status\"\r\n        ) and va.voided = 0\r\nwhere\r\nv.date_stopped is null and\r\nv.visit_type_id=17\r\norder by en.encounter_datetime asc',NULL,'74e43089-f6fd-4f6b-a5cd-6af310d939d6',NULL,NULL,NULL,NULL,NULL,NULL);
REPLACE INTO `global_property` VALUES ('emrapi.sqlSearch.queue.activePatients','select distinct concat(pn.given_name,\" \", ifnull(pn.family_name,\"\")) as name,\n                    primaryIdentifier.identifier as identifier,\n                    IF(extraIdentifier.identifier IS NULL OR extraIdentifier.identifier = \'\', primaryIdentifier.identifier, extraIdentifier.identifier) as \"extraIdentifierVal\",\n                    concat(\"\",p.uuid) as uuid,\n                    concat(\"\",v.uuid) as activeVisitUuid,\n                    IF(va.value_reference = \"Admitted\", \"true\", \"false\") as hasBeenAdmitted,\n                    r.queueNumber as queueNumber\n                from visit v\n                    join person_name pn on v.patient_id = pn.person_id and pn.voided = 0\n                    join person p on p.person_id = v.patient_id\n                    JOIN (SELECT pri.patient_id, pri.identifier\n                        FROM patient_identifier pri\n                            join patient_identifier_type pit on pri.identifier_type = pit.patient_identifier_type_id\n                            join global_property gp on gp.property=\"bahmni.primaryIdentifierType\" and gp.property_value=pit.uuid) primaryIdentifier\n                        ON v.patient_id = primaryIdentifier.patient_id\n                    left outer JOIN (SELECT ei.patient_id, ei.identifier\n                        FROM patient_identifier ei\n                            join patient_identifier_type pit on ei.identifier_type = pit.patient_identifier_type_id\n                            join global_property gp on gp.property=\"bahmni.extraPatientIdentifierTypes\" and pit.uuid=left(gp.property_value, 36)) extraIdentifier\n                        ON v.patient_id = extraIdentifier.patient_id\n                    join location l on l.uuid = ${visit_location_uuid} and v.location_id = l.location_id\n                    left outer join visit_attribute va on va.visit_id = v.visit_id and va.attribute_type_id = (\n                        select visit_attribute_type_id from visit_attribute_type where name=\"Admission Status\") and va.voided = 0\n                    left join (select a.visit_id, count(*) as queueNumber\n                        from (select qv.visit_id, qv.date_started as queueTime\n                            from visit qv\n                            join location ql on ql.uuid = ${visit_location_uuid} and ql.location_id = qv.location_id\n                            where qv.date_stopped is null and qv.voided = 0 and qv.date_started >= curdate()\n                                and exists (select 1 from person_name qn where qn.person_id = qv.patient_id and qn.voided = 0)\n                                and exists (select 1 from patient_identifier qi\n                                join patient_identifier_type qt on qi.identifier_type = qt.patient_identifier_type_id\n                                join global_property qg on qg.property=\"bahmni.primaryIdentifierType\" and qg.property_value=qt.uuid\n                                where qi.patient_id = qv.patient_id)) a\n                        join (select qv.visit_id, qv.date_started as queueTime\n                            from visit qv\n                            join location ql on ql.uuid = ${visit_location_uuid} and ql.location_id = qv.location_id\n                            where qv.date_stopped is null and qv.voided = 0 and qv.date_started >= curdate()\n                                and exists (select 1 from person_name qn where qn.person_id = qv.patient_id and qn.voided = 0)\n                                and exists (select 1 from patient_identifier qi\n                                join patient_identifier_type qt on qi.identifier_type = qt.patient_identifier_type_id\n                                join global_property qg on qg.property=\"bahmni.primaryIdentifierType\" and qg.property_value=qt.uuid\n                                where qi.patient_id = qv.patient_id)) b on (a.queueTime, a.visit_id) >= (b.queueTime, b.visit_id)\n                        group by a.visit_id) r on r.visit_id = v.visit_id\n                where v.date_stopped is null AND v.voided = 0\n                order by queueNumber is null, queueNumber','Active visits at this visit location. queueNumber ranks visits started today by date_started; older open visits get no number.','49f04ab4-9a70-466d-9388-66b0791247e6',NULL,NULL,NULL,NULL,NULL,NULL);
REPLACE INTO `global_property` VALUES ('emrapi.sqlSearch.queue.activePatientsByLocation','select distinct concat(pn.given_name,\" \", ifnull(pn.family_name,\'\')) as name,\n                    pi.identifier as identifier,\n                    concat(\"\",p.uuid) as uuid,\n                    concat(\"\",v.uuid) as activeVisitUuid,\n                    IF(va.value_reference = \"Admitted\", \"true\", \"false\") as hasBeenAdmitted,\n                    r.queueNumber as queueNumber\n                from visit v\n                    join person_name pn on v.patient_id = pn.person_id and pn.voided = 0 and v.voided = 0\n                    join patient_identifier pi on v.patient_id = pi.patient_id and pi.voided = 0\n                    join patient_identifier_type pit on pi.identifier_type = pit.patient_identifier_type_id\n                    join global_property gp on gp.property=\"bahmni.primaryIdentifierType\" and gp.property_value=pit.uuid\n                    join person p on p.person_id = v.patient_id and p.voided = 0\n                    join (select en.visit_id, min(en.encounter_datetime) as queueTime\n                        from encounter en\n                            join encounter_provider ep on ep.encounter_id = en.encounter_id and ep.voided = 0\n                            join provider pr on ep.provider_id = pr.provider_id and pr.retired = 0\n                            join person per on pr.person_id = per.person_id and per.voided = 0\n                            join location loc on en.location_id = loc.location_id\n                        where en.voided = 0 and loc.uuid = ${location_uuid}\n                        group by en.visit_id) q on q.visit_id = v.visit_id\n                    left outer join visit_attribute va on va.visit_id = v.visit_id and va.attribute_type_id = (\n                        select visit_attribute_type_id from visit_attribute_type where name=\"Admission Status\")\n                    left join (select a.visit_id, count(*) as queueNumber\n                        from (select qv.visit_id, min(en.encounter_datetime) as queueTime\n                            from visit qv\n                            join encounter en on en.visit_id = qv.visit_id and en.voided = 0\n                            join encounter_provider ep on ep.encounter_id = en.encounter_id and ep.voided = 0\n                            join provider pr on ep.provider_id = pr.provider_id and pr.retired = 0\n                            join person per on pr.person_id = per.person_id and per.voided = 0\n                            join location loc on en.location_id = loc.location_id\n                            where qv.date_stopped is null and qv.voided = 0 and loc.uuid = ${location_uuid}\n                                and exists (select 1 from person_name qn where qn.person_id = qv.patient_id and qn.voided = 0)\n                                and exists (select 1 from person qp where qp.person_id = qv.patient_id and qp.voided = 0)\n                                and exists (select 1 from patient_identifier qi\n                                join patient_identifier_type qt on qi.identifier_type = qt.patient_identifier_type_id\n                                join global_property qg on qg.property=\"bahmni.primaryIdentifierType\" and qg.property_value=qt.uuid\n                                where qi.patient_id = qv.patient_id and qi.voided = 0)\n                            group by qv.visit_id\n                            having queueTime >= curdate()) a\n                        join (select qv.visit_id, min(en.encounter_datetime) as queueTime\n                            from visit qv\n                            join encounter en on en.visit_id = qv.visit_id and en.voided = 0\n                            join encounter_provider ep on ep.encounter_id = en.encounter_id and ep.voided = 0\n                            join provider pr on ep.provider_id = pr.provider_id and pr.retired = 0\n                            join person per on pr.person_id = per.person_id and per.voided = 0\n                            join location loc on en.location_id = loc.location_id\n                            where qv.date_stopped is null and qv.voided = 0 and loc.uuid = ${location_uuid}\n                                and exists (select 1 from person_name qn where qn.person_id = qv.patient_id and qn.voided = 0)\n                                and exists (select 1 from person qp where qp.person_id = qv.patient_id and qp.voided = 0)\n                                and exists (select 1 from patient_identifier qi\n                                join patient_identifier_type qt on qi.identifier_type = qt.patient_identifier_type_id\n                                join global_property qg on qg.property=\"bahmni.primaryIdentifierType\" and qg.property_value=qt.uuid\n                                where qi.patient_id = qv.patient_id and qi.voided = 0)\n                            group by qv.visit_id\n                            having queueTime >= curdate()) b on (a.queueTime, a.visit_id) >= (b.queueTime, b.visit_id)\n                        group by a.visit_id) r on r.visit_id = v.visit_id\n                where v.date_stopped is null\n                order by queueNumber is null, queueNumber','Active visits with an encounter at this location. queueNumber ranks by the first encounter there, if that was today.','e65f536e-6864-40e9-8822-993238322237',NULL,NULL,NULL,NULL,NULL,NULL);
REPLACE INTO `global_property` VALUES ('emrapi.sqlSearch.queue.activePatientsByProvider','select distinct concat(pn.given_name,\" \", ifnull(pn.family_name,\'\')) as name,\n                    pi.identifier as identifier,\n                    concat(\"\",p.uuid) as uuid,\n                    concat(\"\",v.uuid) as activeVisitUuid,\n                    IF(va.value_reference = \"Admitted\", \"true\", \"false\") as hasBeenAdmitted,\n                    r.queueNumber as queueNumber\n                from visit v\n                    join person_name pn on v.patient_id = pn.person_id and pn.voided = 0 and v.voided = 0\n                    join patient_identifier pi on v.patient_id = pi.patient_id and pi.voided = 0\n                    join patient_identifier_type pit on pi.identifier_type = pit.patient_identifier_type_id\n                    join global_property gp on gp.property=\"bahmni.primaryIdentifierType\" and gp.property_value=pit.uuid\n                    join person p on p.person_id = v.patient_id and p.voided = 0\n                    join (select en.visit_id, min(en.encounter_datetime) as queueTime\n                        from encounter en\n                            join encounter_provider ep on ep.encounter_id = en.encounter_id and ep.voided = 0\n                            join provider pr on ep.provider_id = pr.provider_id and pr.retired = 0\n                            join person per on pr.person_id = per.person_id and per.voided = 0\n                            where en.voided = 0 and pr.uuid = ${provider_uuid}\n                        group by en.visit_id) q on q.visit_id = v.visit_id\n                    join location l on l.uuid = ${visit_location_uuid} and l.location_id = v.location_id\n                    left outer join visit_attribute va on va.visit_id = v.visit_id and va.voided = 0 and va.attribute_type_id = (\n                        select visit_attribute_type_id from visit_attribute_type where name=\"Admission Status\")\n                    left join (select a.visit_id, count(*) as queueNumber\n                        from (select qv.visit_id, min(en.encounter_datetime) as queueTime\n                            from visit qv\n                            join encounter en on en.visit_id = qv.visit_id and en.voided = 0\n                            join encounter_provider ep on ep.encounter_id = en.encounter_id and ep.voided = 0\n                            join provider pr on ep.provider_id = pr.provider_id and pr.retired = 0\n                            join person per on pr.person_id = per.person_id and per.voided = 0\n                            join location ql on ql.uuid = ${visit_location_uuid} and ql.location_id = qv.location_id\n                            where qv.date_stopped is null and qv.voided = 0 and pr.uuid = ${provider_uuid}\n                                and exists (select 1 from person_name qn where qn.person_id = qv.patient_id and qn.voided = 0)\n                                and exists (select 1 from person qp where qp.person_id = qv.patient_id and qp.voided = 0)\n                                and exists (select 1 from patient_identifier qi\n                                join patient_identifier_type qt on qi.identifier_type = qt.patient_identifier_type_id\n                                join global_property qg on qg.property=\"bahmni.primaryIdentifierType\" and qg.property_value=qt.uuid\n                                where qi.patient_id = qv.patient_id and qi.voided = 0)\n                            group by qv.visit_id\n                            having queueTime >= curdate()) a\n                        join (select qv.visit_id, min(en.encounter_datetime) as queueTime\n                            from visit qv\n                            join encounter en on en.visit_id = qv.visit_id and en.voided = 0\n                            join encounter_provider ep on ep.encounter_id = en.encounter_id and ep.voided = 0\n                            join provider pr on ep.provider_id = pr.provider_id and pr.retired = 0\n                            join person per on pr.person_id = per.person_id and per.voided = 0\n                            join location ql on ql.uuid = ${visit_location_uuid} and ql.location_id = qv.location_id\n                            where qv.date_stopped is null and qv.voided = 0 and pr.uuid = ${provider_uuid}\n                                and exists (select 1 from person_name qn where qn.person_id = qv.patient_id and qn.voided = 0)\n                                and exists (select 1 from person qp where qp.person_id = qv.patient_id and qp.voided = 0)\n                                and exists (select 1 from patient_identifier qi\n                                join patient_identifier_type qt on qi.identifier_type = qt.patient_identifier_type_id\n                                join global_property qg on qg.property=\"bahmni.primaryIdentifierType\" and qg.property_value=qt.uuid\n                                where qi.patient_id = qv.patient_id and qi.voided = 0)\n                            group by qv.visit_id\n                            having queueTime >= curdate()) b on (a.queueTime, a.visit_id) >= (b.queueTime, b.visit_id)\n                        group by a.visit_id) r on r.visit_id = v.visit_id\n                where v.date_stopped is null\n                order by queueNumber is null, queueNumber','This provider\'s active visits. queueNumber ranks by the provider\'s first encounter in the visit, if that was today.','e5a0aa92-0f5a-46e3-8015-6496fd53bd15',NULL,NULL,NULL,NULL,NULL,NULL);
